/// 界面字典
/// --------
/// 与 Web 版一样：`zh` 是唯一真相来源，缺键会在这里直接看得出来
/// （回落到 zh，而不是运行时悄悄显示英文 —— 漏译要当场抓包）。
///
/// 三处**刻意保持中文**，与 Web 版一致：
///   1. 许可证条款正文 —— 非官方译文可能造成法律误导（见 licenses 页的标注）；
///   2. 广播出去的 op 内容（打赏 reason / 奖励记录）—— 发出去就固定了；
///   3. 站外链接的平台专名（X / GitHub / Discord）—— 硬译只会让人认不出来。
