/// 取一条文案。缺键按「该语言 → 中文」回落 ——
/// 这样「少一个键」在开发时立刻看得见；运行时悄悄显示英文，只会让人以为翻译坏了。
String tr(String locale, String key, [Map<String, Object>? params]) {
  var s =
      _vault[locale]?[key] ??
      _vault['zh']?[key] ??
      _trust[locale]?[key] ??
      _trust['zh']?[key] ??
      _rank[locale]?[key] ??
      _rank['zh']?[key] ??
      _machine[locale]?[key] ??
      _machine['zh']?[key] ??
      _extra[locale]?[key] ??
      _extra['zh']?[key] ??
      _parity[locale]?[key] ??
      _parity['zh']?[key] ??
      _dicts[locale]?[key] ??
      _zh[key] ??
      key;
  if (params != null) {
    for (final e in params.entries) {
      s = s.replaceAll('{${e.key}}', e.value.toString());
    }
  }
  return s;
}
